sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?birthDate ?deathDate WHERE {
  VALUES ?person { dbr:Jean-Rodolphe_Perronet dbr:Gunnar_Wiklund }

  OPTIONAL { ?person dbp:birthDate ?bDbp . }
  OPTIONAL { ?person dbo:birthDate ?bDbo . }
  BIND (COALESCE(?bDbp, ?bDbo) AS ?birthDate)

  OPTIONAL { ?person dbp:deathDate ?dDbp . }
  OPTIONAL { ?person dbo:deathDate ?dDbo . }
  BIND (COALESCE(?dDbp, ?dDbo) AS ?deathDate)
}
LIMIT 100

